WITH filtered AS (SELECT *, CONCAT_WS('-', event_type, page) AS event_type_page_key, COALESCE(page, 'N/A') AS page_clean FROM web_events WHERE page IS NOT NULL AND event_type != 'purchase'), metrics AS (SELECT *, MAX(duration_sec) OVER (PARTITION BY event_type ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_duration_sec, AVG(duration_sec) OVER (PARTITION BY event_type ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_duration_sec, SUM(duration_sec) OVER (PARTITION BY event_type ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_duration_sec, NTILE(3) OVER (ORDER BY duration_sec ASC, id ASC) AS duration_sec_bucket FROM filtered), joined AS (SELECT src.id, src.session_id, src.event_type, src.page, src.running_avg_duration_sec, src.running_sum_duration_sec, src.duration_sec_bucket, s.browser, s.device FROM metrics src LEFT JOIN sessions s ON src.session_id = s.id WHERE s.started_at < '2024-02-01'), enriched AS (SELECT src.id, src.session_id, src.page, src.running_avg_duration_sec, src.browser, src.device, s.country FROM joined src LEFT JOIN sessions s ON src.session_id = s.id) SELECT s.id, s.session_id, s.page, s.running_avg_duration_sec, s.browser, s.device, s.country, CASE WHEN device RLIKE '^(tablet|desktop)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS device_zone, (SELECT SUM(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS sum_web_event_duration_sec FROM enriched s
